export const customFaviconBase64 = ""; // Paste your Base64 string inside these quotes!

export const setCustomFavicon = () => {
  if (!customFaviconBase64) return;
  
  let link = document.querySelector("link[rel~='icon']");
  if (!link) {
    link = document.createElement('link');
    link.rel = 'icon';
    document.head.appendChild(link);
  }
  link.type = 'image/png';
  link.href = `data:image/png;base64,${customFaviconBase64}`;
};
